#!/usr/bin/env bash
# fix-media-object-route.sh — gallery images 404 because nginx sent /media-object/
# requests to the Next.js frontend instead of the backend (the spec mounts the route
# at app-root, not under /api/v1). Adds the proxy location; nginx.conf is volume-
# mounted so only a restart is needed — no image rebuild.
set -euo pipefail

cd /opt/wedding-app/infra/nginx
cp nginx.conf nginx.conf.bak 2>/dev/null || true
base64 -d > nginx.conf <<'B64_NGINX'

B64_NGINX

echo "== Sanity check =="
grep -cF 'location /media-object/' nginx.conf

echo "== Validating config inside the nginx container =="
docker compose -f /opt/wedding-app/infra/docker-compose.prod.yml exec -T nginx nginx -t

echo "== Restarting nginx =="
cd /opt/wedding-app/infra
docker compose -f docker-compose.prod.yml restart nginx
sleep 5

echo "== Verify: media-object should now 307 to OSS =="
KEY=$(docker compose -f docker-compose.prod.yml exec -T backend uv run python - <<'PYEOF'
import asyncio
from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession, create_async_engine
from src.config import get_settings
from src.models.media import Media

async def m():
    engine = create_async_engine(get_settings().database_url)
    async with AsyncSession(engine) as s:
        r = (await s.execute(select(Media).where(Media.status == "ready").order_by(Media.id.desc()))).scalar_one()
        print(r.thumbnail_path)

asyncio.run(m())
PYEOF
)
echo "testing key: $KEY"
curl -sk -o /dev/null -w 'media-object status: %{http_code} (expect 307)\n' \
  "https://localhost:8443/media-object/$KEY"
curl -sk -L -o /dev/null -w 'full chain status: %{http_code} (expect 200)\n' \
  "https://localhost:8443/media-object/$KEY"

echo "DONE. Hard-refresh the gallery in your browser — images should now load."